"use client";

import * as React from "react";
import {
  Bar,
  BarChart as RechartsBarChart,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { cn } from "@/lib/utils";
import {
  BarFillDefs,
  type BarFillVariant,
  type ChartDatum,
  ChartFrame,
  ChartGlowFilter,
  chartGrid,
  ChartLegend,
  ChartLoadingBars,
  ChartPlotSurface,
  type ChartSeries,
  ChartTooltipContent,
  chartXAxis,
  chartYAxis,
  compactFormatValue,
  barFillUrl,
  createGrowBarShape,
  HoverIndexProvider,
  readActiveTooltipIndex,
  resolveSeries,
  useChartId,
  useChartMotion,
  useIntroStartedAt,
} from "@/components/moneytrees/charts/chart-kit";

export type { BarFillVariant };

export type BarStackType = "none" | "stacked" | "percent";
export type BarLayout = "vertical" | "horizontal";

const VERTICAL_RADIUS = [4, 4, 0, 0] as [number, number, number, number];
const HORIZONTAL_RADIUS = [0, 4, 4, 0] as [number, number, number, number];

export interface SpectrumBarChartProps {
  className?: string;
  data: ChartDatum[];
  xKey: string;
  series: ChartSeries[];
  variant?: BarFillVariant;
  stackType?: BarStackType;
  layout?: BarLayout;
  /** Single-series only: colour each bar up/down by its sign. */
  signed?: boolean;
  glowing?: boolean;
  isLoading?: boolean;
  showLegend?: boolean;
  showGrid?: boolean;
  height?: number;
  formatX?: (value: string | number) => string;
  formatValue?: (value: number) => string;
}

type ResolvedBar = ReturnType<typeof resolveSeries>[number];
type FormatX = ((value: string | number) => string) | undefined;
type FormatValue = ((value: number) => string) | undefined;

function resolveBarLayout(layout: BarLayout) {
  const horizontal = layout === "horizontal";
  return {
    horizontal,
    radius: horizontal ? HORIZONTAL_RADIUS : VERTICAL_RADIUS,
    rechartsLayout: horizontal ? ("vertical" as const) : ("horizontal" as const),
  };
}

function resolveBarStack(stackType: BarStackType) {
  const stacked = stackType !== "none";
  return {
    stackId: stacked ? "stack" : undefined,
    stackOffset: stackType === "percent" ? ("expand" as const) : undefined,
    hideValueAxis: stackType === "percent",
  };
}

function resolveGlowId(id: string, glowing: boolean) {
  const glowId = `${id}-glow`;
  return { glowId, shapeGlowId: glowing ? glowId : undefined };
}

type AxisOptions = {
  horizontal: boolean;
  hideValueAxis: boolean;
  xKey: string;
  formatX: FormatX;
  formatValue: FormatValue;
};

function xAxisProps({ horizontal, hideValueAxis, xKey, formatX, formatValue }: AxisOptions) {
  if (horizontal) {
    return {
      type: "number" as const,
      hide: hideValueAxis,
      tickFormatter: formatValue ?? compactFormatValue,
    };
  }
  return { dataKey: xKey, tickFormatter: formatX };
}

function yAxisProps({ horizontal, hideValueAxis, xKey, formatX, formatValue }: AxisOptions) {
  if (horizontal) {
    return { dataKey: xKey, type: "category" as const, width: 64, tickFormatter: formatX };
  }
  return { hide: hideValueAxis, tickFormatter: formatValue ?? compactFormatValue };
}

function signedCellFill(id: string, variant: BarFillVariant, row: ChartDatum, key: string) {
  const value = Number(row[key] ?? 0);
  const dir = value < 0 ? "down" : "up";
  return barFillUrl(`${id}-${dir}`, variant, `var(--spectrum-chart-${dir})`);
}

function useActiveIndex() {
  const [activeIndex, setActiveIndex] = React.useState<number | null>(null);
  const onMouseMove = (state: { activeTooltipIndex?: number | string | null }) => {
    const next = readActiveTooltipIndex(state);
    setActiveIndex((current) => (current === next ? current : next));
  };
  const onMouseLeave = () => setActiveIndex(null);
  return { activeIndex, onMouseMove, onMouseLeave };
}

function BarChartDefs({
  id,
  bars,
  variant,
  signColors,
  glowing,
  glowId,
}: {
  id: string;
  bars: ResolvedBar[];
  variant: BarFillVariant;
  signColors: boolean;
  glowing: boolean;
  glowId: string;
}) {
  return (
    <>
      {bars.map((s) => (
        <BarFillDefs key={s.key} id={`${id}-${s.key}`} color={s.color} variant={variant} />
      ))}
      {signColors ? (
        <>
          <BarFillDefs id={`${id}-up`} color="var(--spectrum-chart-up)" variant={variant} />
          <BarFillDefs id={`${id}-down`} color="var(--spectrum-chart-down)" variant={variant} />
        </>
      ) : null}
      {glowing ? <ChartGlowFilter id={glowId} /> : null}
    </>
  );
}

export function BarChart({
  className,
  data,
  xKey,
  series,
  variant = "default",
  stackType = "none",
  layout = "vertical",
  signed = false,
  glowing = false,
  isLoading = false,
  showLegend = true,
  showGrid = true,
  height,
  formatX,
  formatValue,
}: SpectrumBarChartProps) {
  const id = useChartId("bar");
  const { reduce } = useChartMotion();
  const introStartedAt = useIntroStartedAt();
  const { activeIndex, onMouseMove, onMouseLeave } = useActiveIndex();
  const bars = resolveSeries(series);
  const { horizontal, radius, rechartsLayout } = resolveBarLayout(layout);
  const { stackId, stackOffset, hideValueAxis } = resolveBarStack(stackType);
  const { glowId, shapeGlowId } = resolveGlowId(id, glowing);
  const signColors = signed && bars.length === 1;
  const axis = { horizontal, hideValueAxis, xKey, formatX, formatValue };

  const shape = React.useMemo(
    () =>
      createGrowBarShape({
        horizontal,
        introStartedAt,
        dataLength: data.length,
        reduce,
        radius,
        stripped: variant === "stripped",
        glowId: shapeGlowId,
      }),
    [horizontal, introStartedAt, data.length, reduce, radius, variant, shapeGlowId],
  );

  return (
    <ChartFrame className={cn("flex flex-col", className)} height={height}>
      {showLegend && bars.length > 1 ? <ChartLegend items={bars} /> : null}
      {isLoading ? (
        <ChartLoadingBars />
      ) : (
        <ChartPlotSurface>
          <HoverIndexProvider value={activeIndex}>
            <ResponsiveContainer width="100%" height="100%">
              <RechartsBarChart
                data={data}
                layout={rechartsLayout}
                stackOffset={stackOffset}
                margin={{ top: 8, right: 8, left: 0, bottom: 0 }}
                barCategoryGap="18%"
                barGap={4}
                onMouseMove={onMouseMove}
                onMouseLeave={onMouseLeave}
              >
                <defs>
                  <BarChartDefs
                    id={id}
                    bars={bars}
                    variant={variant}
                    signColors={signColors}
                    glowing={glowing}
                    glowId={glowId}
                  />
                </defs>
                {showGrid ? (
                  <CartesianGrid {...chartGrid} horizontal={!horizontal} vertical={horizontal} />
                ) : null}
                <XAxis {...chartXAxis} {...xAxisProps(axis)} />
                <YAxis {...chartYAxis} {...yAxisProps(axis)} />
                <Tooltip
                  cursor={{ fill: "currentColor", fillOpacity: 0.05 }}
                  content={<ChartTooltipContent formatValue={formatValue} formatLabel={formatX} />}
                />
                {bars.map((s) => (
                  <Bar
                    key={s.key}
                    dataKey={s.key}
                    name={s.label}
                    fill={barFillUrl(`${id}-${s.key}`, variant, s.color)}
                    radius={radius}
                    stackId={stackId}
                    isAnimationActive={false}
                    shape={shape}
                    maxBarSize={36}
                  >
                    {signColors
                      ? data.map((row, i) => (
                          <Cell
                            key={`${String(row[xKey])}-${i}`}
                            fill={signedCellFill(id, variant, row, s.key)}
                          />
                        ))
                      : null}
                  </Bar>
                ))}
              </RechartsBarChart>
            </ResponsiveContainer>
          </HoverIndexProvider>
        </ChartPlotSurface>
      )}
    </ChartFrame>
  );
}
